      normalizedEmail: "an.declercq@skynet.be",
      phone: "0486 44 55 66",
      normalizedPhone: "+32486445566",
      address: "Kortrijksesteenweg 214",
      postalCode: "9000",
      city: "gent",
      assignedAgentId: thomas.id,
